const pmt = Number(paymentPerPeriod) || 0;
const annual = (Number(annualRatePct) || 0) / 100;
const yrs = Number(years) || 0;
const m = Number(periodsPerYear) || 1;
const i = annual / m;
const N = yrs * m;
const fv = i > 0 ? pmt * ((Math.pow(1 + i, N) - 1) / i) : pmt * N;
const contributed = pmt * N;
const interest = fv - contributed;
const growthPct = contributed > 0 ? (interest / contributed) * 100 : 0;
return { growthPct, fv, interest, contributed };

